solution:
def max_pay(pay: list[int]) -> int:
    before, best = 0, 0                  # best totals up to two days ago and up to yesterday
    for p in pay:
        before, best = best, max(best, before + p)   # skip today, or work it after a day off
    return best

perf.naive:
def max_pay(pay: list[int]) -> int:
    def best(i):                         # most from day i onward, re-solved on every call
        if i >= len(pay):
            return 0
        return max(best(i + 1), pay[i] + best(i + 2))
    return best(0)
